import time
START=time.monotonic()
WORKER="\nimport importlib.util,json,sys,time,traceback\nfrom pathlib import Path\nfrom fractions import Fraction\nsys.dont_write_bytecode=True\nn=int(sys.argv[1]); out=Path(sys.argv[2]); start=float(sys.argv[3])\nstate={'n':n,'stage':'setup','panels':0}\ndef save(name,value):\n    (out/name).write_text(json.dumps(value,sort_keys=True,separators=(',',':'))+'\\n')\ndef progress(stage,panels):\n    state.update(stage=stage,panels=panels)\n    assert time.monotonic()-start<174,'aggregate_work_deadline'\n    save('working.json',{**state,'elapsed_seconds':time.monotonic()-start})\ndef load(name):\n    spec=importlib.util.spec_from_file_location('kernel_'+str(n)+'_'+name,out/(name+'.py'))\n    mod=importlib.util.module_from_spec(spec); spec.loader.exec_module(mod); return mod\ntry:\n    producer=load('producer'); replay=load('replay')\n    parameter=producer.parameter()\n    fixed=json.loads(Path('scripts/first-rational-kernel/step-404/parameter.json').read_text())\n    normalized=json.loads(json.dumps(parameter))\n    assert normalized==fixed,'complete_unchanged_parameter'\n    assert parameter['midpoint']==[73775804382331484748893662180180200545104154546089041648426948815067512948607,2**257]\n    save('parameter.json',parameter)\n    save('parameter-identity.json',{'n':n,'complete_record_equal':True,'midpoint_unchanged':True})\n    progress('production',0)\n    with (out/'panels.jsonl').open('x') as handle:\n        def emit(record):\n            assert record['n']==n\n            handle.write(json.dumps(record,separators=(',',':'))+'\\n')\n            handle.flush()\n        kernel=producer.run(parameter,emit,progress)\n    assert kernel['n']==n and kernel['counts']['coefficient_pairs']==21264880\n    kernel['counts']=dict(kernel['counts'])\n    save('kernel.json',kernel)\n    save('producer-ledger.json',{'n':n,'counts':dict(producer.COUNTS)})\n    progress('replay',0)\n    with (out/'panels.jsonl').open() as handle:\n        report=replay.run(json.loads((out/'parameter.json').read_text()),\n            (json.loads(line) for line in handle),json.loads((out/'kernel.json').read_text()),progress)\n    report['n']=n; report['counts']=dict(report['counts'])\n    assert report['counts']==kernel['counts']==replay.LEDGER\n    assert report['panels']==1016 and report['coefficient_pairs']==21264880\n    radius=Fraction(*kernel['radius'])\n    assert radius<Fraction(1,2**183) and radius<Fraction(1,2**50)\n    assert kernel['final_grid']==[kernel['polynomial_sum'][0]-2**72,kernel['polynomial_sum'][1]+2**72]\n    save('replay-ledger.json',{'n':n,'counts':dict(replay.LEDGER)})\n    save('replay.json',report)\n    save('status.json',{'status':'PASS','n':n,'panels':1016,'pairs_per_pass':21264880,\n        'parameter_complete_equal':True,'ledger_equal':True,'strict_radius_tests':[183,50],\n        'radius':kernel['radius'],'elapsed_seconds':time.monotonic()-start})\n    print(json.dumps({'n':n,'status':'PASS','radius':kernel['radius']}),flush=True)\nexcept BaseException as exc:\n    save('first-failure.json',{'type':type(exc).__name__,'message':str(exc),'state':state,'traceback':traceback.format_exc()})\n    print(json.dumps({'n':n,'status':'STOP','state':state,'error':str(exc)}),flush=True)\n    sys.exit(1)\n"
PARENT='\nimport ast,difflib,hashlib,json,math,signal,subprocess,sys,traceback\nfrom pathlib import Path\nsys.dont_write_bytecode=True\nROOT=Path.cwd(); BASE=ROOT/\'scripts/four-rational-kernels\'; OUT=BASE/\'step-417\'\nLIMIT=134217728; RESERVE=73728\ndef alarm(*args): raise TimeoutError(\'aggregate_180_second_deadline\')\nsignal.signal(signal.SIGALRM,alarm)\nsignal.setitimer(signal.ITIMER_REAL,max(.001,180-(time.monotonic()-START)))\nBASE.mkdir(); OUT.mkdir()\nbootstrap=\'import time\\nSTART=time.monotonic()\\nWORKER=\'+repr(WORKER)+\'\\nPARENT=\'+repr(PARENT)+\'\\nexec(compile(PARENT,"batch-parent","exec"))\\n\'\n(OUT/\'bootstrap.py\').write_text(bootstrap)\n(OUT/\'worker.py\').write_text(WORKER)\nroots=[ROOT/\'scripts/first-rational-kernel\',ROOT/\'scripts/second-rational-kernel\',ROOT/\'scripts/finite-derivative-coefficients\']\nselected=[\n\'lemmas/L031-independent-twist-five-ratio-certificate.md\',\n\'lemmas/L101-conductor389-second-derivative-error-budget.md\',\n\'lemmas/L102-capped-rational-taylor-kernel-enclosures.md\',\n\'lemmas/L103-first-rational-kernel-certificate.md\',\n\'lemmas/L104-second-rational-kernel-certificate.md\',\n\'drafts/literature/2026-10-23-kernels-three-through-six.md\',\n\'drafts/source-notes/2026-10-23-kernels-three-through-six-coverage.md\',\n\'ATTEMPTS/043-complex-order-two-quadratic-coefficient-import.md\',\n\'ATTEMPTS/045-index-128-table-source-adaptation-stop.md\',\n\'ATTEMPTS/046-fixed-derivative-backend-unavailable.md\',\n\'drafts/2026-10-23-four-kernel-attempt.md\']\ninitial={}; sources={}; completed=[]; exits=[]; failure=None; current=None\ndef sha(raw): return hashlib.sha256(raw).hexdigest()\ndef inventory(paths):\n    return {str(p.relative_to(ROOT)):{\'sha256\':sha(p.read_bytes()),\'bytes\':p.stat().st_size} for p in sorted(set(paths))}\ndef disk(): return sum(p.stat().st_size for p in BASE.rglob(\'*\') if p.is_file())\ndef save(name,value):\n    raw=(json.dumps(value,sort_keys=True,separators=(\',\',\':\'))+\'\\n\').encode()\n    assert disk()+len(raw)+RESERVE<=LIMIT,\'aggregate_new_byte_cap\'\n    (OUT/name).write_bytes(raw)\ndef workcheck():\n    assert time.monotonic()-START<174,\'aggregate_work_deadline\'\n    assert disk()+RESERVE<=LIMIT,\'aggregate_new_byte_cap\'\ntry:\n    paths=[p for root in roots for p in root.rglob(\'*\') if p.is_file()]+[ROOT/p for p in selected]\n    initial=inventory(paths)\n    old_names={str(p.relative_to(ROOT)) for root in roots for p in root.rglob(\'*\') if p.is_file()}\n    save(\'initial-inventory.json\',initial)\n    save(\'manifest.json\',{\'step\':\'BSD-2026-10-23-417-four-kernel-batch\',\'indices\':[3,4,5,6],\n        \'python\':sys.version,\'required_seconds\':180,\'work_deadline_seconds\':174,\n        \'required_new_bytes\':LIMIT,\'report_and_diagnostic_reserve\':RESERVE,\n        \'midpoint\':\'unchanged complete L103 record\',\'panels_per_kernel\':1016,\n        \'factor_slots\':[129,65,65],\'product_slots\':[193,257],\'pairs_per_pass\':21264880,\n        \'scalar_terms\':128,\'scalar_squares\':16,\'grid_fractional_bits\':256,\n        \'analytic_enlargement_grid\':2**72,\'strict_radius_powers\':[183,50],\n        \'source_generation_in_cap\':True,\'isolated_modules_per_child\':True,\n        \'old_entrypoints_executed\':False,\'no_retry_or_resumption\':True})\n    for n in (3,4,5,6):\n        current=n; workcheck()\n        dest=OUT/(\'n-\'+str(n)); dest.mkdir()\n        replacements={\n          \'producer.py\':[\n            (\'Isolated step-412 n=2 producer.\',f\'Isolated step-417 n={n} producer.\'),\n            (\'assert 0 < 2*u*a8 < v*8*(1 << 16)//8\',f\'assert 0 < {n}*u*a8 < v*8*(1 << 16)//8\'),\n            (\'exponential(2*u*a8, v*8*(1 << 16))\',f\'exponential({n}*u*a8, v*8*(1 << 16))\'),\n            (\'assert 0 < 2*u <= 64*v\',f\'assert 0 < {n}*u <= 64*v\'),\n            (\'cv(2*u, 8*v)\',f\'cv({n}*u, 8*v)\'),\n            ("record = {\'index\': index,","record = {\'n\': "+str(n)+", \'index\': index,"),\n            ("\'n\': 2}","\'n\': "+str(n)+"}")],\n          \'replay.py\':[\n            (\'Independent isolated step-412 n=2 replay;\',f\'Independent isolated step-417 n={n} replay;\'),\n            (\'assert 0 < num*endpoint*2 < den*65536\',f\'assert 0 < num*endpoint*{n} < den*65536\'),\n            (\'exp_series(num*endpoint*2, den*524288)\',f\'exp_series(num*endpoint*{n}, den*524288)\'),\n            (\'assert 0 < num*2 <= den*64\',f\'assert 0 < num*{n} <= den*64\'),\n            (\'enclose(num*2, den*8)\',f\'enclose(num*{n}, den*8)\'),\n            ("reconstructed = {\'index\': index,","reconstructed = {\'n\': "+str(n)+", \'index\': index,"),\n            ("\'n\': 2}","\'n\': "+str(n)+"}")]}\n        diff=[]; review={}\n        for name,pairs in replacements.items():\n            before=(ROOT/\'scripts/second-rational-kernel/step-412\'/name).read_text()\n            after=before\n            for a,b in pairs:\n                assert after.count(a)==1,(\'unique_exact_adaptation\',n,name,a)\n                after=after.replace(a,b,1)\n            ast.parse(after)\n            (dest/name).write_text(after)\n            assert (dest/name).read_text()==after\n            review[name]=[{\'old\':a,\'new\':b} for a,b in pairs]\n            sources[str((dest/name).relative_to(ROOT))]={\'sha256\':sha(after.encode()),\'bytes\':len(after.encode())}\n            diff.extend(difflib.unified_diff(before.splitlines(True),after.splitlines(True),fromfile=\'step-412/\'+name,tofile=\'n-\'+str(n)+\'/\'+name))\n        (dest/\'source-diff.txt\').write_text(\'\'.join(diff))\n        (dest/\'source-review.json\').write_text(json.dumps({\'n\':n,\'unique_exact_changes\':review,\n            \'both_scalar_and_beta_arguments_bound\':True,\'midpoint_not_scaled\':True,\n            \'all_independent_arithmetic_and_full_loops_unchanged\':True},sort_keys=True)+\'\\n\')\n        workcheck()\n        child_start=time.monotonic()-START\n        try:\n            result=subprocess.run([sys.executable,\'-B\',str(OUT/\'worker.py\'),str(n),str(dest),repr(START)],\n                capture_output=True,timeout=max(.001,174-(time.monotonic()-START)))\n            stdout,stderr=result.stdout,result.stderr\n            returncode=result.returncode\n        except subprocess.TimeoutExpired as exc:\n            stdout,stderr=exc.stdout or b\'\',exc.stderr or b\'\'\n            returncode=None\n            failure={\'type\':\'ChildTimeout\',\'n\':n,\'message\':\'aggregate work deadline; child killed and waited\'}\n        assert len(stdout)+len(stderr)<=8192,\'child_diagnostic_allowance\'\n        (dest/\'child-stdout.txt\').write_bytes(stdout); (dest/\'child-stderr.txt\').write_bytes(stderr)\n        exits.append({\'n\':n,\'returncode\':returncode,\'start_seconds\':child_start,\'observed_exit_seconds\':time.monotonic()-START})\n        save(\'observed-child-exits.json\',exits)\n        if failure is not None: break\n        if returncode!=0:\n            failure={\'type\':\'ChildFailure\',\'n\':n,\'returncode\':returncode,\n                \'evidence\':str((dest/\'first-failure.json\').relative_to(ROOT))}\n            break\n        status=json.loads((dest/\'status.json\').read_text())\n        assert status[\'status\']==\'PASS\' and status[\'n\']==n\n        completed.append(status)\n        save(\'completed-kernels.json\',completed)\n        workcheck()\nexcept BaseException as exc:\n    if failure is None:\n        failure={\'type\':type(exc).__name__,\'message\':str(exc),\'n\':current,\'traceback\':traceback.format_exc()}\nfinally:\n    # Same terminal deadline, never cleared; all children have exited or been killed/waited.\n    signal.setitimer(signal.ITIMER_REAL,max(.001,180-(time.monotonic()-START)))\n    final=inventory([ROOT/p for p in initial])\n    names={str(p.relative_to(ROOT)) for root in roots for p in root.rglob(\'*\') if p.is_file()}\n    mismatches=[p for p in initial if initial[p]!=final.get(p)]\n    fresh_paths=[OUT/\'bootstrap.py\',OUT/\'worker.py\']+[ROOT/p for p in sources]\n    # bootstrap/worker bytes are compared with the original exact source strings.\n    source_ok=(OUT/\'bootstrap.py\').read_text()==bootstrap and (OUT/\'worker.py\').read_text()==WORKER\n    source_ok=source_ok and inventory([ROOT/p for p in sources])==sources\n    preserved=not mismatches and names==old_names and source_ok\n    save(\'source-hashes.json\',inventory(fresh_paths))\n    save(\'preservation.json\',{\'count\':len(initial),\'files\':final,\'mismatches\':mismatches,\n        \'original_tree_file_sets_equal\':names==old_names,\'fresh_sources_equal\':source_ok,\'all_match\':preserved})\n    if not preserved and failure is None: failure={\'type\':\'PreservationFailure\',\'message\':str(mismatches)}\n    if failure is not None: save(\'first-failure.json\',failure)\n    elapsed=time.monotonic()-START\n    sec_bound=math.ceil(elapsed)+2; byte_bound=disk()+RESERVE\n    okay=failure is None and len(completed)==4 and [r[\'n\'] for r in completed]==[3,4,5,6] and sec_bound<=180 and byte_bound<=LIMIT\n    terminal={\'status\':\'PASS\' if okay else \'STOP\',\'completed_indices\':[r[\'n\'] for r in completed],\n        \'failure\':failure,\'child_exits\':exits,\'preserved_inputs\':len(initial),\'preservation\':preserved,\n        \'elapsed_before_terminal_seconds\':elapsed,\'inclusive_seconds\':sec_bound,\'inclusive_new_bytes\':byte_bound,\n        \'required_seconds\':180,\'required_new_bytes\':LIMIT,\'terminal_timer_retained\':True,\n        \'path\':str((OUT/\'terminal-report.json\').relative_to(ROOT))}\n    save(\'terminal-report.json\',terminal)\n    after=time.monotonic()-START\n    save(\'finalization.json\',{\'elapsed_after_terminal_seconds\':after,\'new_bytes_after_terminal\':disk(),\n        \'inclusive_seconds\':sec_bound,\'inclusive_new_bytes\':byte_bound,\'all_children_observed_before_terminal\':True,\n        \'parent_exit_time_not_claimed\':True,\'terminal_timer_retained\':True})\n    assert time.monotonic()-START<=sec_bound<=180\n    assert disk()+8192<=byte_bound<=LIMIT\n    print(json.dumps(terminal),flush=True)\n    assert time.monotonic()-START<=sec_bound\n    sys.exit(0 if okay else 1)\n'
exec(compile(PARENT,"batch-parent","exec"))
